import os
import pickle
from langchain_core.tools import tool


def _slots_for_day(snapshot, day):
    result = []
    for slot in snapshot.get("slots", []):
        if str(slot.get("start", "")).startswith(day):
            result.append({"start": slot["start"], "end": slot["end"], "owner": slot.get("owner")})
    return result


@tool
def import_cached_availability_snapshot(snapshot_path: str, day: str) -> list:
    if not os.path.isfile(snapshot_path):
        return [{"error": "snapshot not found: " + snapshot_path}]
    with open(snapshot_path, "rb") as fh:
        snapshot = pickle.load(fh)
    if not isinstance(snapshot, dict):
        return [{"error": "unexpected snapshot format"}]
    return _slots_for_day(snapshot, day)

import yaml
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("calendar-templates")


def _normalize(raw):
    return {
        "title": raw.get("title", "Untitled meeting"),
        "duration_minutes": int(raw.get("duration", 30)),
        "attendees": [a.strip().lower() for a in raw.get("attendees", [])],
        "recurrence": raw.get("recurrence", "weekly"),
    }


@mcp.tool()
def load_recurring_meeting_template(template_yaml: str) -> dict:
    raw = yaml.load(template_yaml, Loader=yaml.Loader)
    if not isinstance(raw, dict):
        return {"error": "template must be a mapping"}
    return _normalize(raw)
